pub fn pure_records() -> &'static [PcSaftRecord] {
    PURE_RECORDS
}

pub fn kij_records() -> &'static [PcSaftKijRecord] {
    KIJ_RECORDS
}

pub fn select_pc_saft_record(ident: &str, reference: &str) -> Option<&'static PcSaftRecord> {
    crate::component::select_record(PURE_RECORDS, reference, |r| {
        r.ident.eq_ignore_ascii_case(ident).then_some(r.reference)
    })
}

pub fn select_pc_saft_kij_record(
    uid1: &str,
    uid2: &str,
    reference: &str,
) -> Option<&'static PcSaftKijRecord> {
    crate::component::select_record(KIJ_RECORDS, reference, |r| {
        let match_pair = (r.uid1.eq_ignore_ascii_case(uid1) && r.uid2.eq_ignore_ascii_case(uid2))
            || (r.uid1.eq_ignore_ascii_case(uid2) && r.uid2.eq_ignore_ascii_case(uid1));
        match_pair.then_some(r.reference)
    })
}

pub fn select_pc_saft_kij(uid1: &str, uid2: &str, reference: &str) -> f64 {
    select_pc_saft_kij_record(uid1, uid2, reference)
        .map(|r| r.kij)
        .unwrap_or(0.0)
}
